commands.code:
kubectl patch deployment slow-start -n drill --type=json -p='[
  {"op":"replace","path":"/spec/template/spec/containers/0/livenessProbe/initialDelaySeconds","value":30},
  {"op":"replace","path":"/spec/template/spec/containers/0/livenessProbe/failureThreshold","value":3}
]'
kubectl rollout status -n drill deployment/slow-start
kubectl get pods -n drill                          # RESTARTS stops climbing, 1/1 Running

kubectl patch deployment checkout -n drill --type=json -p='[
  {"op":"replace","path":"/spec/template/spec/containers/0/readinessProbe/failureThreshold","value":3}
]'
kubectl rollout status -n drill deployment/checkout
watch -n1 "kubectl get endpoints checkout -n drill"                           # confirm: stays steady near 3, no more flapping

kubectl get pods -n drill                                    # 0/1 Pending
kubectl describe pod batch -n drill                          # FailedScheduling: untolerated taint {dedicated: gpu}
kubectl describe nodes | grep Taints                         # confirms dedicated=gpu:NoSchedule on nodes
